   </details>

+- `23.17` Behind the top of the page is a faded photograph of the city hosting the festival that leads the trip.
+
+  ![planng-city-photo.23.17](requirements/screen/cases/planng-city-photo.23.17.png) <!-- req-gallery:23.17 -->
+
+  <details><summary>Notes</summary>
+
+  One photograph per host city, stored with the site: Jerusalem, Haifa, Akko
+  and Edinburgh. Faint enough that the timeline and the page's own palette
+  read first, it fades out down the page before the calendar starts, so no
+  day or show is ever drawn over a picture. A festival whose city has no
+  photograph keeps the plain wash. The picture is decoration and carries no
+  text for a screen reader.
+  </details>
+
+- `23.18` When another festival comes to lead the trip, its city's photograph fades in over the last one rather than jumping, unless you ask your device for reduced motion.
+
+  🚩 _Behavior leaf._ <!-- req-gallery:23.18 -->
+
+  <details><summary>Notes</summary>
+
+  The same fade as the colours (23.10), over the same time. A behavior leaf
+  for the same reason: a golden freezes every transition at its end, so the
+  case lifts the freeze and samples both photographs' opacity part-way.
+  </details>
+
+- `23.19` The footer credits the photograph on show: its title, linked to its source, its photographer and its licence, linked to the licence.
+
+  ![planng-photo-credit.23.19](requirements/screen/cases/planng-photo-credit.23.19.png) <!-- req-gallery:23.19 -->
+
 ## 24. How you are getting here

 The page asks, once, how the reader is getting to the festival, and only when
diff --git a/product/requirements/behavior/cases/planng-photo-fade.23.18.case.js b/product/requirements/behavior/cases/planng-photo-fade.23.18.case.js
new file mode 100644
index 0000000..fd17ec8
--- /dev/null
+++ b/product/requirements/behavior/cases/planng-photo-fade.23.18.case.js
@@ -0,0 +1,79 @@
+"use strict";
+const { jerusalemReady, plannerReady } = require("../../shared/case-helpers");
+
+/* The city photographs cross-fading. As with the colours (23.10), the harness
+ * freezes every transition for its goldens, so this case lifts the freeze and
+ * reads both photographs' opacity frame by frame. */
+const JERUSALEM = "/planNG/cities/jerusalem.webp";
+const HAIFA = "/planNG/cities/haifa.webp";
+
+async function unfreeze(page) {
+  await page.evaluate(() => {
+    for (const s of document.querySelectorAll("style")) {
+      if (s.textContent.includes("transition-duration: 0s !important")) s.remove();
+    }
+  });
+}
+
+/* Each photograph's opacity, keyed by its file, on every frame from Haifa's
+ * photograph being lit until the fade must be over. */
+async function fadeFrames(page) {
+  const frames = page.evaluate(
+    () =>
+      new Promise((resolve) => {
+        const host = document.getElementById("cityBackdrop");
+        const read = () =>
+          Object.fromEntries(
+            [...host.querySelectorAll("img")].map((i) => [i.dataset.src, Number(getComputedStyle(i).opacity)])
+          );
+        const seen = [];
+        new MutationObserver((_, observer) => {
+          const lit = host.querySelector("img.is-on");
+          if (!lit || lit.dataset.src !== "/planNG/cities/haifa.webp") return;
+          observer.disconnect();
+          const until = performance.now() + 900;
+          const sample = () => {
+            seen.push(read());
+            if (performance.now() < until) requestAnimationFrame(sample);
+            else resolve(seen);
+          };
+          sample();
+        }).observe(host, { attributes: true, subtree: true, childList: true, attributeFilter: ["class"] });
+      })
+  );
+  await page.click('.tl-item[data-festival="haifa-iff"]');
+  return frames;
+}
+
+module.exports = {
+  description: "choosing another festival fades its city's photograph in over the last one, and switches at once under reduced motion",
+  page: "/planNG/?festival=jerusalem-comedy",
+  viewport: "desktop",
+  async verify(page, { origin, assert }) {
+    await page.goto(`${origin}/planNG/?festival=jerusalem-comedy`, { waitUntil: "load" });
+    await jerusalemReady(page);
+    await unfreeze(page);
+
+    const frames = await fadeFrames(page);
+    await plannerReady(page, "haifa-iff");
+    const first = frames[0];
+    const last = frames[frames.length - 1];
+    assert.ok(first[JERUSALEM] > 0, `Jerusalem's photograph is still showing as Haifa's is lit (${JSON.stringify(first)})`);
+    assert.equal(last[JERUSALEM], 0, "Jerusalem's photograph has gone once the fade is over");
+    assert.ok(last[HAIFA] > 0, "Haifa's photograph shows once the fade is over");
+    assert.ok(
+      frames.some((f) => f[HAIFA] > 0 && f[HAIFA] < last[HAIFA] && f[JERUSALEM] > 0),
+      `part-way through, both photographs show, each part-faded: a cross-fade rather than a cut (${JSON.stringify(frames)})`
+    );
+
+    await page.emulateMedia({ reducedMotion: "reduce" });
+    await page.goto(`${origin}/planNG/?festival=jerusalem-comedy`, { waitUntil: "load" });
+    await jerusalemReady(page);
+    await unfreeze(page);
+    const still = await fadeFrames(page);
+    assert.ok(
+      still.every((f) => f[JERUSALEM] === 0 && f[HAIFA] === last[HAIFA]),
+      `with reduced motion asked for, the photograph switches at once (${JSON.stringify(still)})`
+    );
+  },
+};
