import json, sys

def trunc(s, n=220):
    s = str(s)
    s = s.replace("\n", " \\n ")
    if len(s) > n:
        return s[:n] + "...[%d chars]" % len(s)
    return s

def summarize_block(b):
    t = b.get("type")
    if t == "text":
        return "TEXT: " + trunc(b.get("text",""))
    if t == "tool_use":
        name = b.get("name")
        inp = b.get("input", {})
        return "TOOL_USE[%s]: %s" % (name, trunc(json.dumps(inp)))
    if t == "tool_result":
        content = b.get("content")
        if isinstance(content, list):
            content = " ".join(str(c.get("text","")) for c in content if isinstance(c, dict))
        is_err = b.get("is_error")
        return "TOOL_RESULT%s: %s" % (" [ERROR]" if is_err else "", trunc(content))
    if t == "thinking":
        return "THINKING: " + trunc(b.get("thinking",""), 120)
    return "BLOCK[%s]: %s" % (t, trunc(b))

def main(path):
    with open(path) as fh:
        for line in fh:
            line = line.strip()
            if not line:
                continue
            try:
                d = json.loads(line)
            except Exception:
                continue
            typ = d.get("type")
            ts = d.get("timestamp","")
            if typ in ("assistant","user"):
                msg = d.get("message", {})
                role = msg.get("role", typ)
                content = msg.get("content")
                if isinstance(content, str):
                    print(f"{ts} [{role}] TEXT: {trunc(content)}")
                elif isinstance(content, list):
                    for b in content:
                        if isinstance(b, dict):
                            print(f"{ts} [{role}] {summarize_block(b)}")
                        else:
                            print(f"{ts} [{role}] RAW: {trunc(b)}")
            elif typ == "attachment":
                att = d.get("attachment", {})
                at = att.get("type")
                if at in ("hook_success","hook_additional_context"):
                    hookname = att.get("hookName")
                    content = att.get("content") or att.get("stdout") or ""
                    print(f"{ts} [hook:{hookname}] {trunc(content, 180)}")
            elif typ == "queue-operation":
                print(f"{ts} [queue] {trunc(d.get('content',''), 150)}")

if __name__ == "__main__":
    main(sys.argv[1])

