1951	export function patternRule(declaration, { selfExclude = null } = {}) {
1952	  const where = `the declared check "${declaration.id}"`;
1953	  if (typeof declaration.id !== 'string' || !declaration.id.trim()) {
1954	    throw new Error('a declared check needs a non-empty "id"');
1955	  }
1956	  if (declaration.severity !== 'blocking' && declaration.severity !== 'advisory') {
1957	    throw new Error(`${where}: severity must be "blocking" or "advisory", not ${JSON.stringify(declaration.severity)}`);
1958	  }
1959	  // `since` is the date the check was authored, and the engine holds a blocking
1960	  // check to advisory for its first GRACE_DAYS from it (findings.mjs). Validated
