[
  {
    "id": "edfringe-no-review-request-from-pr-author",
    "severity": "blocking",
    "since": "2026-09-26",
    "scope": "action",
    "failureMessage": "every PR in this repo is opened under the one account (missingbulb) that also owns it, so GitHub always rejects a review request naming that same account (\"Review cannot be requested from pull request author\") — a call worth skipping rather than repeating",
    "guardToolCalls": [
      {
        "tool": "/^mcp__github__(create|update)_pull_request$/",
        "inputField": "reviewers",
        "match": "/missingbulb/i",
        "what": "a {tool} call requesting review from \"missingbulb\", the PR's own author",
        "fix": "drop missingbulb from reviewers — assigning them, or leaving reviewers empty, is what a review request was reaching for"
      }
    ]
  }
]
